/* stepper */
.stp{max-width:430px}
.stp-head{display:flex;align-items:center;padding:16px;border-bottom:1px solid var(--line)}
.stp-i{display:flex;align-items:center;gap:8px;font-size:12.5px;font-weight:600;color:var(--muted);white-space:nowrap;transition:color .3s}
.stp-i b{width:22px;height:22px;display:grid;place-items:center;border:1px solid var(--icon-line);font-size:11px;transition:background-color .3s,border-color .3s,color .3s}
.stp-i.cur{color:var(--text)}
.stp-i.cur b{border-color:var(--accent);color:var(--accent)}
.stp-i.done b{background:var(--accent);border-color:var(--accent);color:#fff}
.stp-ln{flex:1;height:2px;margin:0 10px;background:var(--line);position:relative;overflow:hidden}
.stp-ln i{position:absolute;inset:0;background:var(--accent);transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.stp-ln.done i{transform:none}
.stp-body{padding:16px}
.stp-body .fz{margin-bottom:12px}
.stp-hint{font-size:12.5px;color:var(--muted)}
.stp-plans{display:flex;flex-direction:column;gap:8px}
.stp-plan{display:flex;align-items:center;gap:12px;padding:12px;border:1px solid var(--icon-line);text-align:left;transition:border-color .2s,box-shadow .2s}
.stp-plan.on{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg)}
.stp-plan .t{font-size:13.5px;font-weight:600}
.stp-plan .d{font-size:12.5px;color:var(--muted)}
.stp-plan .p{margin-left:auto;font-family:var(--mono);font-size:13px;font-weight:700}
.stp-foot{display:flex;justify-content:space-between;padding:12px 16px;border-top:1px solid var(--line)}
.stp-foot .btn[disabled]{opacity:.4}

/* ---------- stepper ---------- */
{
  const head = $('#stp-head'), body = $('#stp-body'), back = $('#stp-back'), next = $('#stp-next');
  const names = ['Workspace','Invite','Plan'];
  let step = 0, ws = '', emails = '', plan = 'Pro';
  function render(first){
    head.innerHTML = names.map((n, i) => `${i ? `<span class="stp-ln ${i <= step ? 'done' : ''}"><i></i></span>` : ''}<span class="stp-i ${i < step ? 'done' : i === step ? 'cur' : ''}"><b>${i < step ? '✓' : i + 1}</b>${n}</span>`).join('');
    const put = () => {
      if (step === 0) body.innerHTML = `<div class="enter"><div class="fz" id="stp-ws-f"><label class="fz-l" for="stp-ws">Workspace name</label><div class="fz-in"><input id="stp-ws" placeholder="Northwind Labs" value="${esc(ws)}" autocomplete="off"></div><span class="fz-e">Give your workspace a name</span></div><div class="stp-hint" id="stp-url">Your URL will be designme.dev/${ws ? ws.toLowerCase().replace(/[^a-z0-9]+/g, '-') : 'your-team'}</div></div>`;
      else if (step === 1) body.innerHTML = `<div class="enter"><div class="fz"><label class="fz-l" for="stp-em">Invite by email</label><div class="fz-in"><input id="stp-em" placeholder="maya@northwind.co, oscar@northwind.co" value="${esc(emails)}" autocomplete="off"></div></div><div class="stp-hint">You can skip this and invite people later.</div></div>`;
      else body.innerHTML = `<div class="enter stp-plans">${[['Starter','For trying it out','$0'],['Pro','For small teams','$24'],['Team','Shared libraries and SSO','$48']].map(p => `<button class="stp-plan ${p[0] === plan ? 'on' : ''}" data-p="${p[0]}"><span><span class="t" style="display:block">${p[0]}</span><span class="d">${p[1]}</span></span><span class="p">${p[2]}</span></button>`).join('')}</div>`;
      const w = $('#stp-ws'); if (w) w.addEventListener('input', () => { ws = w.value; $('#stp-ws-f').classList.remove('err'); $('#stp-url').textContent = 'Your URL will be designme.dev/' + (ws ? ws.toLowerCase().replace(/[^a-z0-9]+/g, '-') : 'your-team'); });
      const em = $('#stp-em'); if (em) em.addEventListener('input', () => { emails = em.value; });
    };
    first ? put() : morph(body.parentElement, put);
    back.disabled = step === 0; swapText($('#stp-next-t'), step === 2 ? 'Create workspace' : step === 1 && !emails ? 'Skip for now' : 'Continue');
  }
  body.addEventListener('click', e => { const b = e.target.closest('.stp-plan'); if (!b) return; plan = b.dataset.p; $$('.stp-plan', body).forEach(x => x.classList.toggle('on', x === b)); Sound.play('select'); });
  next.addEventListener('click', () => {
    if (step === 0 && !ws.trim()){ $('#stp-ws-f').classList.add('err'); Sound.play('fail'); return; }
    if (step === 2){ Sound.play('done'); showToast(`${ws} created on ${plan}`); step = 0; ws = ''; emails = ''; plan = 'Pro'; render(); return; }
    step++; Sound.play('tab'); render();
  });
  back.addEventListener('click', () => { if (step){ step--; Sound.play('tab'); render(); } });
  render(true);
}
